s = input().strip()
n = int(input())
t = int(input())

length = len(s)

# Build the position permutation for one complete sequence.
perm = list(range(length))

for _ in range(n):
    op = input().split()
    command = op[0]

    if command == "R":
        perm.reverse()

    elif command == "L":
        k = int(op[1]) % length
        perm = perm[k:] + perm[:k]

    elif command == "S":
        a, b = int(op[1]), int(op[2])
        perm[a], perm[b] = perm[b], perm[a]

    elif command == "B":
        k = int(op[1])
        size = length // k

        blocks = [
            perm[i * size:(i + 1) * size]
            for i in range(k)
        ]

        perm = [
            position
            for block in reversed(blocks)
            for position in block
        ]

    elif command == "P":
        for i in range(0, length, 4):
            perm[i:i + 4] = (
                perm[i + 2:i + 4] +
                perm[i:i + 2]
            )

# Invert the permutation to undo one complete sequence.
inv = [0] * length

for i in range(length):
    inv[perm[i]] = i

# Apply the inverse permutation T times using cycle decomposition.
result = [""] * length
visited = [False] * length

for i in range(length):
    if visited[i]:
        continue

    cycle = []
    j = i

    while not visited[j]:
        visited[j] = True
        cycle.append(j)
        j = inv[j]

    shift = t % len(cycle)

    for pos in range(len(cycle)):
        result[cycle[pos]] = s[cycle[(pos + shift) % len(cycle)]]

print("".join(result))
